A \emph{structure} $\Sigma$ is a collection $(\Sigma_n)_{n \in \mathbb N}$, where each $\Sigma_n$ is a boolean algebra of subsets of $\mathbb R^n$ and the following holds:
\begin{itemize}
\item[(i)] if $A \in \Sigma_n$ and $B \in \Sigma_m$, then $A \times B \in \Sigma_{n+m}$;
\item[(ii)] if $A \in \Sigma_n$ and $p_i \colon \mathbb R^{n} \to \mathbb R^{n-1}$ is the standard projection $$(x_1, \ldots, x_n) \mapsto (x_1, \ldots x_{i-1},x_{i+1}  \ldots, x_{n-1}),$$ then $p_i(A) \in \Sigma_{n-1}$;
\item[(iii)] every semi-algebraic subset $A \subseteq \mathbb R^n$ is in $\Sigma_n$. Recall, that $A$ is semi-algebraic if it can be defined using a finite system of real polynomial inequalities.
\end{itemize}
The elements of $\Sigma_n$ are called ($\Sigma$-)\emph{definable sets}.
If $A \in \Sigma_n$ and $B \in \Sigma_m$ are two definable sets, then a map $f \colon A \to B$ is called \emph{definable} if its graph $\Gamma_f \subseteq A \times B$ is definable.

\label{o-min nice}
Let $\Sigma$ be an o-minimal structure.
\begin{itemize}
\item[(i)] A $\Sigma$-definable set is connected if and only if it is path-connected;
\item[(ii)] definable sets admit \emph{finite cell decomposition}: every definable $A \subset \mathbb R^n$ can be written as $A = A_1 \sqcup \ldots \sqcup A_k$, where each $A_j \subseteq A$ is a locally closed definable subset definably homeomorphic to $\mathbb R^{n_j}$. In particular, every definable set has finitely many connected components and is homotopically equivalent to a finite CW-complex;
\item[(iii)] definable functions are piecewise-continuous; moreover, if $A$ is a definable set and $f \colon A \to \mathbb R$ is a definable map, for every $k \ge 0$ there exists a finite decomposition $A = A_1 \sqcup \ldots \sqcup A_m$ into definable locally closed sets $A_j$ such that $f|_{A_j}$ is of class $\mathcal{C}^{k}$;
\item[(iv)] if $A \subseteq \mathbb R$ is a definable subset of $\mathbb R$ and $f \colon A \to \mathbb R$ is a definable function, then its derivative $f'$ is definable whenever it exists.
\end{itemize}

\label{dif top space}
Let $\Sigma$ be an o-minimal structure and $X$ a topological space. A $\Sigma$-\emph{definable atlas} $\xi=(U_{\alpha}, \phi_{\alpha})_{\alpha \in A}$ is a finite collection of open charts $U_{\alpha}, \ X = \bigcup_{\alpha} U_{\alpha}$ and  homeomorphic embeddings $\phi_{\alpha} \colon U_{\alpha} \to \mathbb R^{n}$, such that 
\begin{itemize}
\item[(i)] $\phi_{\alpha}(U_{\alpha} \cap U_{\beta})$ are $\Sigma$-definable in $\mathbb R^n$ for every $\alpha$ and $\beta$;
\item[(ii)] the transition functions $\phi_\beta \circ \phi_{\alpha}^{-1} \colon \phi_{\alpha}(U_{\alpha} \cap U_{\beta}) \to \phi_{\beta}(U_{\alpha} \cap U_{\beta})$ are $\Sigma$-definable. 
\end{itemize} 
A $\Sigma$-definable topological space is a topological space $X$ with a fixed equivalence class of $\Sigma$-definable atlases.

\label{o-min cover}
Let $X$ be a topological space and $\xi$ a $\Sigma$-definable atlas on $X$ for an o-minimal structure $\Sigma$. Assume that $\pi_1(X)$ is finite. Then the following holds:
\begin{itemize}
\item[(i)] The universal cover $\widetilde{X}$ admits a unique $\Sigma$-definable atlas $\widetilde{\xi}$ such that the covering map $p \colon \widetilde{X} \to X$ is definable;
\item[(ii)] if $Y$ is a simply connected $\Sigma$-definable space and $f \colon Y \to X$ is continuous and $\Sigma$-definable, the canonical lifting $\widetilde{f} \colon Y \to \widetilde{X}$ is $\Sigma$-definable.
 \end{itemize}

\label{def vector bundles basics}
Let $M$ be a definable smooth manifold, $E \to M$ a definable vector bundle. Then:
\begin{itemize}
\item[(i)] $E^*, \ \Lambda^kE, \ \operatorname{Sym}^kE$ carry natural definable structures;
\item[(ii)] if $F$ is another definable vector bundle, then $E \otimes F, \ Hom(E, F), \ E \oplus F$ carry natural definable structures;
\item[(iii)] the trace morphism $\operatorname{tr} \colon E \otimes E^* \to \mathbb R_M$ is definable;
\item[(iv)] a morphism $f \colon F \to E$ is definable if and only if it is definable as a section of $Hom(E, F)$;
\item[(v)]a morphism $f \colon E \to F$ is definable if and only if it determines a definable map $\operatorname{Tot}(E) \to \operatorname{Tot}(F)$. If $\operatorname{ker} f$ (resp. $\operatorname{coker} f$) is a vector bundle, it carries a natural definable structure;
\item[(vi)] if $N$ is a definable manifold and $f \colon N \to M$ is a definable smooth map, then $f^*E$ carries a natural definable structure;
\end{itemize}

\label{def connection}
Let $M$ be a smooth definable manifold and $E \to M$ a definable smooth vector bundle.
\begin{itemize}
\item[(i)] if $\nabla$ is a definable connection on $E$, then for every definable section $s \in \mathcal{C}^{\infty}(M, E)$ the section $\nabla s \in \mathcal{C}^{\infty}(M , E \otimes T^{*}M)$ is definable;
\item[(ii)] if $g$ is a definable metric on $M$, its Levi-Civita connection is definable. 
\end{itemize}

\label{Weyl inv}
Let $(M, g)$ be a Riemannian manifold. We define the class of \emph{Weyl invariants} among the tensors on $M$ as the following:
\begin{itemize}
\item $g$ is a Weyl invariant;
\item the curvature tensor $R_g$ is a Weyl invariant;
\item if $\tau$ is a Weyl invariant and $\nabla$ is the Levi-Civita connection, $\nabla \tau$ is a Weyl invariant;
\item a linear combination of Weyl invariants is a Weyl invariant;
\item if $\tau \in (TM)^{\otimes p} \otimes (T^*M)^{\otimes q}$ is a Weyl invariant, then its image under any tensorial convolution $$(TM)^{\otimes p} \otimes (T^*M)^{\otimes q} \to (TM)^{\otimes (p-k)} \otimes (T^*M)^{\otimes (q-k)}$$  is a Weyl invariant.
\end{itemize}

\label{co theorem}
Let $(M,g)$ be a Riemannian manifold and let $$W_M=(w_1, \ldots, w_k) \colon M \to \mathbb R^k$$ be as above. Then the following holds:
\begin{itemize}
\item[(i)] every Killing vector field on $(M, g)$ is tangent to the level sets of $W_M$;
\item[(ii)] if $N \subseteq M$ is a non-critical level set of $W_M$, then $(N, g|_N)$ is a locally  homogeneous Riemann manifold;
\item[(iii)] for every $W_M$-non-critical point $x \in M$ there exists a neighbourhood $U$ of $x$ and a collection of Killing vector fields $\xi_1, \ldots, \xi_r \in \mathcal{C}^{\infty}(U, TM|_U)$  that generate $\operatorname{Ker} dW_M$ as an $\mathcal{C}^{\infty}(U)$-module.
\end{itemize}

\label{bi-def top}
Let $i \colon N \hookrightarrow M$ be a  strongly bi-definable subset. Let $\widetilde{N}:=\pi^{-1}(N)$. The following holds:
\begin{itemize}
\item[(1)] for any ring R the cohomology algebra $H^{\bullet}(\widetilde{N}, R)$ is finitely generated;
\item[(2)] The image of $i_*\colon \pi_1(N) \to \pi_1(M)$ is of finite index in $\pi_1(M)$.
\end{itemize}
